export const READING_EXTRA: ReadingTest[] = [
  {"id":"gen-renting-a-flat-rights-an","title":"Renting a Flat: Rights and Responsibilities","format":"general","minutes":15,"topic":"Жильё и аренда","passage":{"heading":"Understanding Tenancy Agreements and Deposits","paragraphs":["When renting a flat, the tenancy agreement is the most important document. It outlines the rights and responsibilities of both landlords and tenants. A standard agreement includes details such as rent amount, payment due dates, and the duration of the tenancy. Tenants should read this document carefully before signing, as it is legally binding. Any special conditions, like restrictions on pets or subletting, will also be listed here.","Most landlords require a security deposit, usually equivalent to one or two months’ rent. This deposit acts as financial protection against damages or unpaid rent. However, landlords cannot withhold the deposit without valid reasons. In many countries, deposits must be held in a government-approved scheme, ensuring fair treatment for tenants.","Finding compatible housemates can make shared renting more enjoyable. Clear communication about chores, bills, and lifestyle preferences is essential. Some flatshares create a written agreement between housemates to avoid disputes. Topics like overnight guests, noise levels, and shared expenses should be discussed openly.","Tenants have the right to a safe and habitable living environment. Landlords must ensure the property meets health and safety standards, including working smoke alarms and proper heating. Repairs should be reported promptly, and landlords are responsible for fixing issues that affect livability.","At the end of a tenancy, tenants must leave the property in good condition to receive their full deposit back. Landlords may deduct money for damages beyond normal wear and tear. To avoid disputes, it’s advisable to document the property’s condition with photos before moving in and after moving out.","Breaking a tenancy agreement early can have financial consequences. Tenants may need to pay rent until a new tenant is found or forfeit part of their deposit. However, some agreements include break clauses allowing early termination under specific conditions.","Renting with pets can be challenging, as many landlords prohibit them due to potential damage. Tenants with pets should seek pet-friendly properties or negotiate terms with the landlord. An additional pet deposit may be required to cover any damages.","Understanding local rental laws can help tenants protect their rights. Many regions have tenant unions or advisory services that offer free guidance. Knowledge of these resources can prevent exploitation and resolve disputes effectively."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Landlords can withhold a tenant’s deposit for any reason.","answer":["FALSE"],"why":"В тексте указано, что арендодатели не могут удерживать депозит без веских причин ('landlords cannot withhold the deposit without valid reasons')."},{"id":"q2","kind":"tfng","prompt":"A tenancy agreement must be signed before moving into a rented property.","answer":["TRUE"],"why":"В тексте говорится, что соглашение является юридически обязательным, и арендаторы должны прочитать его перед подписанием ('it is legally binding')."},{"id":"q3","kind":"tfng","prompt":"All countries require landlords to hold deposits in government-approved schemes.","answer":["NOT GIVEN"],"why":"В тексте упоминается, что во многих странах депозиты должны храниться в утвержденных схемах, но не сказано, что это правило действует везде."},{"id":"q4","kind":"tfng","prompt":"Housemates should avoid discussing financial arrangements to prevent disagreements.","answer":["FALSE"],"why":"Текст рекомендует открыто обсуждать общие расходы ('shared expenses should be discussed openly'), чтобы избежать споров."},{"id":"q5","kind":"tfng","prompt":"Landlords are responsible for ensuring the property has functioning smoke alarms.","answer":["TRUE"],"why":"В тексте указано, что арендодатели должны обеспечивать соответствие стандартам безопасности, включая исправные пожарные извещатели ('working smoke alarms')."}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What is the main purpose of a security deposit?","options":["A To cover the landlord’s mortgage payments","B To protect against damages or unpaid rent","C To pay for renovations before moving in","D To reduce the monthly rent amount"],"answer":["B"],"why":"В тексте сказано, что депозит служит финансовой защитой от повреждений или неуплаты аренды ('financial protection against damages or unpaid rent')."},{"id":"q7","kind":"mcq","prompt":"What should tenants do to maximize the return of their deposit?","options":["A Avoid reporting minor repairs","B Document the property’s condition with photos","C Negotiate a lower deposit amount","D Skip the final cleaning"],"answer":["B"],"why":"Текст рекомендует фотографировать состояние имущества при въезде и выезде ('document the property’s condition with photos'), чтобы избежать споров."},{"id":"q8","kind":"mcq","prompt":"Why might renting with pets be difficult?","options":["A Landlords always charge higher rent for pets","B Most properties automatically allow pets","C Landlords often prohibit pets due to potential damage","D Tenants must pay a monthly pet fee"],"answer":["C"],"why":"В тексте указано, что многие арендодатели запрещают домашних животных из-за возможного ущерба ('many landlords prohibit them due to potential damage')."},{"id":"q9","kind":"mcq","prompt":"What can help tenants resolve disputes with landlords?","options":["A Ignoring the tenancy agreement","B Withholding rent payments","C Seeking advice from tenant unions","D Refusing to communicate"],"answer":["C"],"why":"Текст упоминает, что знание местных законов и консультационных служб ('advisory services') помогает разрешать споры."}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"A tenancy agreement is a _______ document that tenants must read carefully.","answer":["legally"],"why":"В тексте говорится, что соглашение является 'legally binding' (юридически обязательным)."},{"id":"q11","kind":"gap","prompt":"Landlords must ensure properties meet health and _______ standards.","answer":["safety"],"why":"Текст упоминает 'health and safety standards' (стандарты здоровья и безопасности)."},{"id":"q12","kind":"gap","prompt":"Breaking a tenancy agreement early may result in financial _______.","answer":["consequences"],"why":"В тексте сказано, что досрочное расторжение может иметь 'financial consequences' (финансовые последствия)."},{"id":"q13","kind":"gap","prompt":"Tenants with pets may need to pay an additional _______.","answer":["deposit"],"why":"Текст указывает, что может потребоваться 'additional pet deposit' (дополнительный депозит за питомца)."}]}]},
  {"id":"gen-urban-transport-and-sust","title":"Urban Transport and Sustainable Cities","format":"academic","minutes":20,"topic":"Города и транспорт","passage":{"heading":"Balancing Mobility and Urban Space","paragraphs":["Cities worldwide are grappling with the dual challenges of providing efficient transport systems while maintaining livable urban environments. As populations grow, the demand for mobility increases, often leading to congestion, pollution, and reduced public space. Many cities have turned to innovative solutions to address these issues, such as congestion charging, expanded public transit, and dedicated bike lanes.","Congestion charging, first implemented in London in 2003, involves levying a fee on vehicles entering designated urban zones during peak hours. This policy aims to reduce traffic density by discouraging unnecessary car use and encouraging public transport or cycling. Studies have shown that congestion charging can decrease traffic volumes by up to 20%, while also cutting greenhouse gas emissions.","Another approach is the creation of dedicated bike lanes, which not only promote cycling but also reclaim public space for pedestrians. Cities like Copenhagen and Amsterdam have demonstrated that investing in cycling infrastructure can significantly reduce car dependency. These lanes encourage healthier lifestyles, reduce air pollution, and create more vibrant urban spaces.","Public transport remains a cornerstone of sustainable urban mobility. Efficient bus and rail systems can move large numbers of people quickly, reducing the number of private vehicles on the road. Cities like Tokyo and Singapore have invested heavily in their transit networks, ensuring accessibility and reliability for millions of commuters daily.","However, these solutions require careful planning and public support. Congestion charges, for example, can be unpopular among drivers, while bike lanes may face resistance from businesses concerned about parking space. Successful implementation often depends on transparent communication and gradual policy rollouts.","Ultimately, the goal is to create cities where transport systems coexist harmoniously with public spaces. This requires a shift in mindset, prioritizing collective well-being over individual convenience. By investing in sustainable transport, cities can enhance their residents' quality of life while addressing pressing environmental challenges.","Innovative urban transport strategies also have economic benefits. Reduced congestion lowers the cost of goods transportation, while improved public health leads to lower healthcare expenses. Furthermore, vibrant public spaces attract tourism and foster community engagement, contributing to a city's economic vitality.","As cities continue to evolve, the integration of transport and urban planning will remain critical. Policymakers must balance immediate needs with long-term sustainability, ensuring that transport systems serve not only today's residents but also future generations."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Congestion charging was first introduced in London in 2003.","answer":["TRUE"],"why":"Текст утверждает: 'Congestion charging, first implemented in London in 2003'."},{"id":"q2","kind":"tfng","prompt":"Cities like Copenhagen have eliminated all car use.","answer":["FALSE"],"why":"Текст упоминает, что Копенгаген уменьшил зависимость от автомобилей, но не говорит о полном устранении."},{"id":"q3","kind":"tfng","prompt":"Public transport systems are less efficient than private vehicles.","answer":["FALSE"],"why":"Текст утверждает: 'Efficient bus and rail systems can move large numbers of people quickly'."},{"id":"q4","kind":"tfng","prompt":"Congestion charging is universally popular among drivers.","answer":["FALSE"],"why":"Текст указывает: 'Congestion charges can be unpopular among drivers'."},{"id":"q5","kind":"tfng","prompt":"Economic benefits of urban transport strategies include lower healthcare costs.","answer":["TRUE"],"why":"Текст сообщает: 'improved public health leads to lower healthcare expenses'."}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What is the primary goal of congestion charging?","options":["A To increase city revenue","B To reduce traffic density","C To promote cycling","D To expand public spaces"],"answer":["B"],"why":"Текст поясняет: 'This policy aims to reduce traffic density by discouraging unnecessary car use'."},{"id":"q7","kind":"mcq","prompt":"Which city is NOT mentioned for its investment in cycling infrastructure?","options":["A Copenhagen","B Amsterdam","C Tokyo","D London"],"answer":["C"],"why":"Текст упоминает Копенгаген, Амстердам и Лондон, но не Токио в контексте велосипедной инфраструктуры."},{"id":"q8","kind":"mcq","prompt":"What is a key factor in the successful implementation of transport policies?","options":["A Economic incentives","B Public support","C Technological innovation","D Government funding"],"answer":["B"],"why":"Текст подчеркивает: 'Successful implementation often depends on transparent communication and gradual policy rollouts'."},{"id":"q9","kind":"mcq","prompt":"What broader goal do urban transport strategies aim to achieve?","options":["A Economic growth","B Environmental sustainability","C Collective well-being","D Technological advancement"],"answer":["C"],"why":"Текст утверждает: 'This requires a shift in mindset, prioritizing collective well-being over individual convenience'."}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Congestion charging can reduce traffic volumes by up to ______ percent.","answer":["20"],"why":"Текст сообщает: 'congestion charging can decrease traffic volumes by up to 20%'."},{"id":"q11","kind":"gap","prompt":"Dedicated bike lanes reclaim public space for ______.","answer":["pedestrians"],"why":"Текст указывает: 'dedicated bike lanes... reclaim public space for pedestrians'."},{"id":"q12","kind":"gap","prompt":"Cities like Tokyo and Singapore have invested heavily in their ______ networks.","answer":["transit"],"why":"Текст упоминает: 'Cities like Tokyo and Singapore have invested heavily in their transit networks'."},{"id":"q13","kind":"gap","prompt":"Innovative transport strategies contribute to a city's ______ vitality.","answer":["economic"],"why":"Текст сообщает: 'vibrant public spaces... contributing to a city's economic vitality'."}]}]},
  {"id":"gen-evening-courses-and-trai","title":"Evening Courses and Training Programs","format":"general","minutes":15,"topic":"Курсы и обучение","passage":{"heading":"Evening Courses: Policies and Procedures","paragraphs":["Evening courses are offered throughout the year, with new sessions starting every quarter. These courses cater to individuals seeking to enhance their skills or pursue personal interests outside regular working hours. Topics range from language learning and computer skills to photography and creative writing. Each course is designed to accommodate busy schedules, typically running for eight weeks with sessions held twice a week.","Enrolment is open to anyone aged 18 or older. Prospective students must complete an application form, which can be submitted online or in person at the registration office. Early registration is encouraged, as courses often fill up quickly. Payment is required at the time of enrolment, and fees vary depending on the course duration and materials provided. Discounts are available for students who enrol in multiple courses or refer a friend.","Refund requests must be made within the first week of the course. A full refund will be issued if the request is submitted before the second session. After this period, refunds are only granted under exceptional circumstances, such as illness or relocation. All refund requests require supporting documentation and are subject to approval by the course coordinator.","Timetables are published two weeks before the start of each quarter. Students are advised to check the timetable carefully, as changes may occur due to unforeseen circumstances. In the event of a cancellation, students will be notified via email and offered the option to transfer to another course or receive a full refund.","Attendance is crucial for success in evening courses. Students who miss more than three sessions may be required to repeat the course or forfeit their certification. Instructors are available for consultation during office hours, and additional resources, such as online materials and practice exercises, are provided to support learning.","Feedback from students is highly valued and used to improve course offerings. At the end of each session, participants are encouraged to complete an evaluation form. Suggestions for new courses or improvements to existing ones are always welcome and can be submitted to the course administration office."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Evening courses are available year-round.","answer":["TRUE"],"why":"В тексте указано: 'Evening courses are offered throughout the year.'"},{"id":"q2","kind":"tfng","prompt":"Discounts are available for students who enrol in three or more courses.","answer":["NOT GIVEN"],"why":"В тексте упоминаются скидки за несколько курсов, но точное количество не указано."},{"id":"q3","kind":"tfng","prompt":"Refunds are never issued after the second session.","answer":["FALSE"],"why":"В тексте сказано: 'After this period, refunds are only granted under exceptional circumstances.'"},{"id":"q4","kind":"tfng","prompt":"Timetables are subject to change.","answer":["TRUE"],"why":"В тексте указано: 'Students are advised to check the timetable carefully, as changes may occur.'"},{"id":"q5","kind":"tfng","prompt":"Instructors are only available during class hours.","answer":["FALSE"],"why":"В тексте указано: 'Instructors are available for consultation during office hours.'"}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What is the minimum age requirement for enrolling in evening courses?","options":["A 16","B 18","C 20","D 21"],"answer":["B"],"why":"В тексте сказано: 'Enrolment is open to anyone aged 18 or older.'"},{"id":"q7","kind":"mcq","prompt":"When are timetables published?","options":["A One week before the quarter","B Two weeks before the quarter","C At the start of the quarter","D After enrolment"],"answer":["B"],"why":"В тексте указано: 'Timetables are published two weeks before the start of each quarter.'"},{"id":"q8","kind":"mcq","prompt":"What happens if a course is cancelled?","options":["A Students receive a partial refund","B Students are automatically enrolled in another course","C Students are notified via email","D Students lose their fees"],"answer":["C"],"why":"В тексте сказано: 'In the event of a cancellation, students will be notified via email.'"},{"id":"q9","kind":"mcq","prompt":"What is the consequence of missing more than three sessions?","options":["A Students must pay a fine","B Students forfeit certification","C Students are expelled","D Students receive extra homework"],"answer":["B"],"why":"В тексте указано: 'Students who miss more than three sessions may be required to repeat the course or forfeit their certification.'"}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Refunds require ______ documentation.","answer":["supporting"],"why":"В тексте сказано: 'All refund requests require supporting documentation.'"},{"id":"q11","kind":"gap","prompt":"Courses typically last for ______ weeks.","answer":["eight"],"why":"В тексте указано: 'Each course is designed to accommodate busy schedules, typically running for eight weeks.'"},{"id":"q12","kind":"gap","prompt":"Students are encouraged to provide ______ at the end of each session.","answer":["feedback"],"why":"В тексте сказано: 'Feedback from students is highly valued and used to improve course offerings.'"},{"id":"q13","kind":"gap","prompt":"Additional resources include ______ exercises.","answer":["practice"],"why":"В тексте указано: 'Additional resources, such as online materials and practice exercises, are provided to support learning.'"}]}]},
  {"id":"gen-global-water-crisis-and-","title":"Global Water Crisis and Solutions","format":"academic","minutes":20,"topic":"Экология и вода","passage":{"heading":"Addressing Water Scarcity Through Innovation and Policy","paragraphs":["Water scarcity has emerged as one of the most pressing global challenges of the 21st century. With population growth, urbanization, and climate change exacerbating the issue, over two billion people now live in regions experiencing high water stress. Agriculture accounts for approximately 70% of freshwater withdrawals worldwide, making it a critical sector for conservation efforts. Innovative irrigation techniques, such as drip irrigation and precision agriculture, have shown promise in reducing water waste while maintaining crop yields.","Desalination technology has gained traction as a potential solution for water-scarce coastal regions. While traditional thermal desalination methods are energy-intensive, reverse osmosis has become more energy-efficient in recent years. However, the environmental impact of brine discharge remains a concern. Researchers are exploring ways to utilize brine in industrial applications or dilute it more effectively before returning it to the ocean.","Urban water conservation strategies have also proven effective in reducing water consumption. Cities like Cape Town, which faced severe water shortages in 2018, implemented strict water rationing and public awareness campaigns. These measures successfully reduced water consumption by over 50% during the crisis. Rainwater harvesting systems and greywater recycling have become increasingly popular in urban areas, reducing demand for potable water in non-drinking applications.","Policy interventions play a crucial role in water management. Many countries are implementing water pricing mechanisms that reflect the true cost of water delivery and treatment. Such policies encourage conservation while generating revenue for infrastructure maintenance and upgrades. Additionally, transboundary water agreements have become essential for managing shared water resources between countries, particularly in regions prone to drought.","Technological advancements in water monitoring have improved resource management. Smart sensors and satellite imagery now enable real-time tracking of water usage and quality. These tools help detect leaks, monitor irrigation efficiency, and identify pollution sources. Artificial intelligence is being employed to predict water demand patterns and optimize distribution systems.","Education and community engagement have emerged as vital components of water conservation efforts. School programs teaching water literacy and household water-saving techniques have shown significant impact in changing consumption patterns. Indigenous water management practices are increasingly recognized for their sustainability and are being integrated into modern water governance frameworks.","While challenges remain, a combination of technological innovation, policy reform, and behavioral change offers hope for addressing global water scarcity. The integration of traditional knowledge with modern science presents opportunities for developing more sustainable water management systems. As water scarcity continues to affect more regions, collaborative efforts across sectors will be crucial for ensuring water security for future generations."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Agriculture is responsible for the majority of global freshwater withdrawals.","answer":["TRUE"],"why":"В тексте говорится, что 'Agriculture accounts for approximately 70% of freshwater withdrawals worldwide'."},{"id":"q2","kind":"tfng","prompt":"Reverse osmosis has become less energy-efficient in recent years.","answer":["FALSE"],"why":"В тексте указано, что 'reverse osmosis has become more energy-efficient in recent years.'"},{"id":"q3","kind":"tfng","prompt":"Cape Town increased its water consumption during the 2018 crisis.","answer":["FALSE"],"why":"В тексте сказано, что 'These measures successfully reduced water consumption by over 50% during the crisis.'"},{"id":"q4","kind":"tfng","prompt":"Artificial intelligence is being used to predict water demand patterns.","answer":["TRUE"],"why":"В тексте упоминается, что 'Artificial intelligence is being employed to predict water demand patterns.'"},{"id":"q5","kind":"tfng","prompt":"Indigenous water management practices are now considered outdated.","answer":["FALSE"],"why":"В тексте сказано, что 'Indigenous water management practices are increasingly recognized for their sustainability.'"}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What percentage of freshwater withdrawals does agriculture account for globally?","options":["A 50%","B 60%","C 70%","D 80%"],"answer":["C"],"why":"В тексте указано: 'Agriculture accounts for approximately 70% of freshwater withdrawals worldwide.'"},{"id":"q7","kind":"mcq","prompt":"Which technology has become more energy-efficient for desalination?","options":["A Thermal distillation","B Reverse osmosis","C Electro-dialysis","D Nanofiltration"],"answer":["B"],"why":"В тексте сказано: 'reverse osmosis has become more energy-efficient in recent years.'"},{"id":"q8","kind":"mcq","prompt":"What percentage reduction in water consumption did Cape Town achieve during its crisis?","options":["A 30%","B 40%","C 50%","D 60%"],"answer":["C"],"why":"В тексте указано: 'These measures successfully reduced water consumption by over 50% during the crisis.'"},{"id":"q9","kind":"mcq","prompt":"What is being used to predict water demand patterns?","options":["A Satellite imagery","B Smart sensors","C Artificial intelligence","D Traditional forecasting"],"answer":["C"],"why":"В тексте говорится: 'Artificial intelligence is being employed to predict water demand patterns.'"}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Agriculture accounts for approximately 70% of global ______ withdrawals.","answer":["freshwater"],"why":"В тексте сказано: 'Agriculture accounts for approximately 70% of freshwater withdrawals worldwide.'"},{"id":"q11","kind":"gap","prompt":"Reverse osmosis has become more ______ in recent years.","answer":["energy-efficient"],"why":"В тексте указано: 'reverse osmosis has become more energy-efficient in recent years.'"},{"id":"q12","kind":"gap","prompt":"Cape Town implemented strict water ______ during its crisis.","answer":["rationing"],"why":"В тексте говорится: 'implemented strict water rationing and public awareness campaigns.'"},{"id":"q13","kind":"gap","prompt":"Artificial intelligence helps ______ water demand patterns.","answer":["predict"],"why":"В тексте сказано: 'Artificial intelligence is being employed to predict water demand patterns.'"}]}]},
  {"id":"gen-urban-transport-innovati","title":"Urban Transport Innovations","format":"academic","minutes":20,"topic":"Города и транспорт","passage":{"heading":"Rethinking Urban Mobility","paragraphs":["Urban transport systems are under increasing pressure as cities grow and populations rise. Traditional solutions, such as expanding road networks, often fail to address congestion effectively. Instead, many cities are turning to innovative approaches like congestion charging, which aims to reduce traffic by imposing fees on vehicles entering busy areas during peak hours. London, for instance, implemented such a scheme in 2003, resulting in a 15% reduction in traffic within the charging zone.","Another strategy gaining popularity is the development of dedicated bike lanes. These lanes not only encourage cycling but also reduce conflicts between cyclists and motorists. Cities like Copenhagen and Amsterdam have seen significant increases in cycling rates after investing in extensive bike lane networks. This shift not only alleviates traffic but also contributes to lower carbon emissions and improved public health.","Public space reclamation is another emerging trend. Cities are transforming car-centric areas into pedestrian-friendly zones, prioritizing walking over driving. For example, Barcelona’s 'superblocks' initiative restricts vehicle access in certain neighborhoods, creating more space for pedestrians and cyclists. This approach fosters community interaction and enhances the quality of urban life.","However, these innovations face challenges. Congestion charging schemes can be unpopular among drivers who perceive them as unfair. Similarly, bike lanes often require significant investment and face opposition from those who prioritize car infrastructure. Public space reclamation, too, can lead to disputes over land use and economic impacts on local businesses.","Despite these challenges, the benefits of these strategies are clear. Reduced traffic congestion leads to shorter travel times and lower pollution levels. Increased cycling and walking contribute to healthier populations. Reclaimed public spaces enhance urban aesthetics and community well-being. As cities continue to evolve, these innovations will play a crucial role in shaping sustainable urban transport systems.","Looking ahead, technology will likely drive further advancements. Autonomous vehicles, for example, could revolutionize urban transport by optimizing traffic flow and reducing accidents. Smart city initiatives, integrating data and technology, could enable more efficient management of transport systems. These developments, combined with existing strategies, offer a promising future for urban mobility."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Congestion charging was first introduced in London in 2003.","answer":["TRUE"],"why":"В тексте говорится: 'London, for instance, implemented such a scheme in 2003.'"},{"id":"q2","kind":"tfng","prompt":"Bike lanes in Copenhagen have led to a decrease in cycling rates.","answer":["FALSE"],"why":"В тексте указано: 'Cities like Copenhagen [...] have seen significant increases in cycling rates.'"},{"id":"q3","kind":"tfng","prompt":"Public space reclamation always receives unanimous support from local businesses.","answer":["FALSE"],"why":"В тексте говорится, что 'Public space reclamation [...] can lead to disputes over land use and economic impacts on local businesses.'"},{"id":"q4","kind":"tfng","prompt":"Autonomous vehicles are expected to reduce traffic accidents.","answer":["TRUE"],"why":"В тексте сказано: 'Autonomous vehicles [...] could revolutionize urban transport by [...] reducing accidents.'"},{"id":"q5","kind":"tfng","prompt":"Smart city initiatives are unrelated to urban transport management.","answer":["FALSE"],"why":"В тексте указано: 'Smart city initiatives [...] could enable more efficient management of transport systems.'"}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What was the primary goal of London’s congestion charging scheme?","options":["A Increase revenue","B Reduce traffic","C Promote cycling","D Expand road networks"],"answer":["B"],"why":"В тексте сказано: 'congestion charging [...] aims to reduce traffic.'"},{"id":"q7","kind":"mcq","prompt":"Which cities are mentioned as examples of successful bike lane networks?","options":["A Paris and Berlin","B Copenhagen and Amsterdam","C New York and Tokyo","D Barcelona and Rome"],"answer":["B"],"why":"В тексте указано: 'Cities like Copenhagen and Amsterdam have seen significant increases in cycling rates.'"},{"id":"q8","kind":"mcq","prompt":"What is the main focus of Barcelona’s 'superblocks' initiative?","options":["A Expanding car access","B Creating pedestrian-friendly zones","C Building more bike lanes","D Increasing public transport"],"answer":["B"],"why":"В тексте говорится: 'Barcelona’s 'superblocks' initiative restricts vehicle access [...] creating more space for pedestrians.'"},{"id":"q9","kind":"mcq","prompt":"What is one challenge of implementing bike lanes?","options":["A Lack of public interest","B Opposition from cyclists","C High investment costs","D Reduced carbon emissions"],"answer":["C"],"why":"В тексте указано: 'Bike lanes often require significant investment.'"}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Congestion charging aims to reduce ______ in busy areas.","answer":["traffic"],"why":"В тексте сказано: 'congestion charging [...] aims to reduce traffic.'"},{"id":"q11","kind":"gap","prompt":"Bike lanes help reduce conflicts between cyclists and ______.","answer":["motorists"],"why":"В тексте указано: 'These lanes [...] reduce conflicts between cyclists and motorists.'"},{"id":"q12","kind":"gap","prompt":"Public space reclamation prioritizes ______ over driving.","answer":["walking"],"why":"В тексте говорится: 'Cities are transforming car-centric areas into pedestrian-friendly zones, prioritizing walking over driving.'"},{"id":"q13","kind":"gap","prompt":"Smart city initiatives integrate ______ and technology for transport management.","answer":["data"],"why":"В тексте сказано: 'Smart city initiatives, integrating data and technology, could enable more efficient management of transport systems.'"}]}]},
  {"id":"gen-the-impact-of-ultra-proc","title":"The Impact of Ultra-Processed Foods on Health","format":"academic","minutes":20,"topic":"Питание и здоровье","passage":{"heading":"The Rise of Ultra-Processed Foods and Their Health Implications","paragraphs":["In recent decades, the consumption of ultra-processed foods (UPFs) has surged globally, particularly in developed nations. These foods, characterized by their industrial formulations and high levels of additives, have become staples in many diets. UPFs are often convenient, affordable, and highly palatable, contributing to their widespread popularity. However, their nutritional value is frequently questioned, as they tend to be high in sugar, salt, and unhealthy fats while lacking essential nutrients.","Research has increasingly linked UPFs to adverse health outcomes. Studies suggest that regular consumption of UPFs is associated with a higher risk of obesity, cardiovascular diseases, and type 2 diabetes. The mechanisms behind these associations are multifaceted, involving factors such as excessive calorie intake, poor nutrient quality, and the potential impact of additives on gut health. Despite these findings, UPFs continue to dominate global food systems, raising concerns about public health.","One area of growing concern is the inclusion of UPFs in school meals. Many school feeding programs rely on processed and pre-packaged foods to meet budgetary constraints and logistical challenges. While these meals may provide calories, they often fail to meet nutritional standards, potentially compromising children's health and development. Critics argue that such practices contribute to the normalization of unhealthy eating habits from an early age.","Efforts to address the issue have included calls for stricter food labelling regulations. Clear and informative labelling could help consumers make healthier choices by identifying UPFs and highlighting their nutritional shortcomings. Some countries have already implemented measures such as front-of-pack warning labels, which indicate high levels of sugar, salt, or fat. However, the effectiveness of these initiatives remains debated, as consumer behaviour is influenced by multiple factors beyond labelling alone.","Nutrition research continues to explore the complexities of UPFs and their impact on health. Emerging studies are examining not only the direct effects of UPFs but also their broader societal implications, including environmental sustainability and economic equity. For instance, the production of UPFs often involves resource-intensive processes, contributing to environmental degradation. Additionally, their affordability makes them disproportionately accessible to lower-income populations, exacerbating health disparities.","Public health advocates emphasize the need for a multi-faceted approach to tackling the UPF problem. This includes promoting whole and minimally processed foods, implementing educational campaigns, and advocating for policy changes. While reversing the trend of UPF consumption is challenging, it is widely regarded as essential for improving population health and reducing the burden of diet-related diseases.","In conclusion, the rise of ultra-processed foods presents a significant public health challenge. Addressing this issue requires concerted efforts from governments, researchers, and consumers alike. By prioritizing nutrition and sustainability, it may be possible to shift food systems towards healthier, more equitable models."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Ultra-processed foods are primarily consumed in developing nations.","answer":["FALSE"],"why":"Текст указывает, что UPFs популярны в развитых странах, а не в развивающихся."},{"id":"q2","kind":"tfng","prompt":"Regular consumption of UPFs is linked to a lower risk of type 2 diabetes.","answer":["FALSE"],"why":"Исследования показывают, что UPFs связаны с повышенным риском диабета 2 типа."},{"id":"q3","kind":"tfng","prompt":"School meals often include ultra-processed foods due to budgetary constraints.","answer":["TRUE"],"why":"В тексте говорится, что школьные программы питания используют UPFs из-за ограниченного бюджета."},{"id":"q4","kind":"tfng","prompt":"Front-of-pack warning labels are universally effective in changing consumer behaviour.","answer":["FALSE"],"why":"Эффективность таких этикеток остается спорной, так как поведение потребителей зависит от множества факторов."},{"id":"q5","kind":"tfng","prompt":"Nutrition research is only focused on the direct health effects of UPFs.","answer":["FALSE"],"why":"Исследования также изучают более широкие аспекты, включая экологию и экономическое неравенство."}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What is a key characteristic of ultra-processed foods?","options":["A High nutritional value","B Low levels of additives","C Industrial formulations","D Minimal processing"],"answer":["C"],"why":"Текст описывает UPFs как продукты промышленного производства."},{"id":"q7","kind":"mcq","prompt":"Which health issue is NOT mentioned as a risk associated with UPF consumption?","options":["A Obesity","B Cardiovascular diseases","C Cancer","D Type 2 diabetes"],"answer":["C"],"why":"Рак не упоминается в тексте как риск, связанный с UPFs."},{"id":"q8","kind":"mcq","prompt":"What is one reason UPFs are included in school meals?","options":["A High nutritional standards","B Logistical challenges","C Consumer preference","D Environmental sustainability"],"answer":["B"],"why":"Логистические трудности упоминаются как причина использования UPFs в школьных обедах."},{"id":"q9","kind":"mcq","prompt":"What broader societal issue is linked to UPF production?","options":["A Increased agricultural diversity","B Environmental degradation","C Improved economic equity","D Reduced health disparities"],"answer":["B"],"why":"Производство UPFs способствует деградации окружающей среды."}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Ultra-processed foods are often high in sugar, salt, and unhealthy ______.","answer":["fats"],"why":"В тексте указано, что UPFs содержат нездоровые жиры."},{"id":"q11","kind":"gap","prompt":"Efforts to address UPFs include stricter food ______ regulations.","answer":["labelling"],"why":"Регулирование маркировки упоминается как мера для борьбы с UPFs."},{"id":"q12","kind":"gap","prompt":"Nutrition research is exploring the ______ implications of UPFs.","answer":["societal"],"why":"Исследования изучают более широкие социальные аспекты UPFs."},{"id":"q13","kind":"gap","prompt":"Public health advocates emphasize the need for a multi-faceted ______.","answer":["approach"],"why":"Текст указывает на необходимость комплексного подхода."}]}]},
  {"id":"gen-the-future-of-work-in-th","title":"The Future of Work in the Digital Age","format":"academic","minutes":20,"topic":"Технологии и работа","passage":{"heading":"The Impact of Digital Transformation on Labour Markets","paragraphs":["The rapid advancement of digital technologies has significantly altered the landscape of global labour markets. Automation, artificial intelligence, and machine learning are increasingly replacing repetitive and routine tasks, leading to a shift in the demand for certain skills. As a result, workers are required to adapt by acquiring new digital competencies to remain competitive in the job market.","Remote work has become a prominent feature of the modern workplace, accelerated by the COVID-19 pandemic. This shift has allowed companies to tap into a global talent pool, reducing geographical constraints. However, it has also introduced challenges related to communication, collaboration, and cybersecurity, necessitating the development of robust digital infrastructures.","The rise of the gig economy and freelance work has further transformed traditional employment models. Platforms like Upwork and Fiverr enable individuals to offer their services on a project basis, providing flexibility but also raising concerns about job security and benefits. This trend underscores the need for policies that address the unique needs of gig workers.","Digital skills are now considered essential across various industries. Proficiency in data analysis, coding, and digital marketing has become crucial for career advancement. Educational institutions and training programs are increasingly focusing on equipping students with these skills to prepare them for the evolving job market.","Despite the benefits of digital transformation, there are concerns about its impact on job displacement. While new roles are being created, many traditional jobs are becoming obsolete. Governments and organizations must collaborate to ensure a smooth transition for workers affected by these changes.","The role of lifelong learning cannot be overstated in this context. Continuous skill development is necessary to keep pace with technological advancements. Online courses, certifications, and micro-credentials offer accessible avenues for professionals to enhance their expertise and adapt to changing industry demands.","In conclusion, the future of work is being shaped by digital transformation, remote work, and the gig economy. While these changes present opportunities, they also pose challenges that require proactive measures. By embracing digital skills and fostering a culture of lifelong learning, individuals and organizations can navigate the complexities of the modern labour market."]},"groups":[{"title":"Questions 1-5","instructions":"Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.","questions":[{"id":"q1","kind":"tfng","prompt":"Automation is primarily replacing tasks that are repetitive and routine.","answer":["TRUE"],"why":"В тексте говорится: 'Automation, artificial intelligence, and machine learning are increasingly replacing repetitive and routine tasks.'"},{"id":"q2","kind":"tfng","prompt":"The gig economy has eliminated all concerns about job security.","answer":["FALSE"],"why":"В тексте указано: 'This trend underscores the need for policies that address the unique needs of gig workers.'"},{"id":"q3","kind":"tfng","prompt":"Educational institutions are not adapting their curricula to include digital skills.","answer":["FALSE"],"why":"В тексте говорится: 'Educational institutions and training programs are increasingly focusing on equipping students with these skills.'"},{"id":"q4","kind":"tfng","prompt":"The COVID-19 pandemic has had no impact on the rise of remote work.","answer":["FALSE"],"why":"В тексте указано: 'Remote work has become a prominent feature of the modern workplace, accelerated by the COVID-19 pandemic.'"},{"id":"q5","kind":"tfng","prompt":"Lifelong learning is becoming less important due to technological advancements.","answer":["FALSE"],"why":"В тексте говорится: 'The role of lifelong learning cannot be overstated in this context.'"}]},{"title":"Questions 6-9","instructions":"Choose the correct letter, A, B, C or D.","questions":[{"id":"q6","kind":"mcq","prompt":"What has accelerated the prominence of remote work?","options":["A Technological advancements","B Economic crises","C COVID-19 pandemic","D Government policies"],"answer":["C"],"why":"В тексте указано: 'Remote work has become a prominent feature of the modern workplace, accelerated by the COVID-19 pandemic.'"},{"id":"q7","kind":"mcq","prompt":"Which of the following is NOT mentioned as a digital skill?","options":["A Data analysis","B Coding","C Digital marketing","D Financial auditing"],"answer":["D"],"why":"В тексте перечислены навыки: 'Proficiency in data analysis, coding, and digital marketing.'"},{"id":"q8","kind":"mcq","prompt":"What is a major concern related to the gig economy?","options":["A Lack of flexibility","B Job security","C Excessive regulation","D Overqualification"],"answer":["B"],"why":"В тексте говорится: 'This trend underscores the need for policies that address the unique needs of gig workers.'"},{"id":"q9","kind":"mcq","prompt":"What is essential for keeping pace with technological advancements?","options":["A Job displacement","B Lifelong learning","C Government policies","D Economic growth"],"answer":["B"],"why":"В тексте указано: 'Continuous skill development is necessary to keep pace with technological advancements.'"}]},{"title":"Questions 10-13","instructions":"Complete the sentences. Choose ONE WORD ONLY from the passage for each answer.","questions":[{"id":"q10","kind":"gap","prompt":"Automation is increasingly replacing ______ tasks.","answer":["routine"],"why":"В тексте говорится: 'Automation, artificial intelligence, and machine learning are increasingly replacing repetitive and routine tasks.'"},{"id":"q11","kind":"gap","prompt":"Remote work allows companies to tap into a global ______ pool.","answer":["talent"],"why":"В тексте указано: 'This shift has allowed companies to tap into a global talent pool.'"},{"id":"q12","kind":"gap","prompt":"The gig economy provides ______ but raises concerns about job security.","answer":["flexibility"],"why":"В тексте говорится: 'Platforms like Upwork and Fiverr enable individuals to offer their services on a project basis, providing flexibility.'"},{"id":"q13","kind":"gap","prompt":"Continuous ______ development is necessary to keep pace with technological advancements.","answer":["skill"],"why":"В тексте указано: 'Continuous skill development is necessary to keep pace with technological advancements.'"}]}]},
];

